  els.overlay.hidden = false;
  const close = (ok) => {
    els.overlay.hidden = true;
    els.ok.onclick = null;
    els.cancel.onclick = null;
    if (ok) onConfirm();
  };
  els.ok.onclick = () => close(true);
  els.cancel.onclick = () => close(false);
