  const out = displayOutcome(events || []);
  const hosts = {};
  for (const host of clean.hosts) {
    hosts[host.id] = {
      state: "clean",
      shield: false,
      jewel: host.id === clean.jewel_host,
      exposed: false,
    };
  }
